function gLoad(){let g=null;try{g=JSON.parse(sget(GKEY)||"null");}catch(e){}
  if(g&&g.v===1&&g.groupes)return g;
  g={v:1,actif:null,habitant:false,groupes:{},quand:{mode:"weekend",du:null,au:null},rayon:20,pluie:false};
  const w=sget("cf-where");if(w)g.rayon=w==="ici"?1.5:w==="10"?10:20;          // reprise des anciens réglages
  try{const st=JSON.parse(sget("cf-stay")||"null");if(st&&st.to>=today()&&sget("pp-mode")==="sejour")g.quand={mode:"dates",du:st.from,au:st.to};}catch(e){}
  if(sget("pp-mode")==="annee")g.habitant=true;
  return g;}
let GR=gLoad();
function gSave(){sset(GKEY,JSON.stringify(GR));}
const gActive=()=>!GR.habitant&&GR.actif&&GR.groupes[GR.actif]?GR.groupes[GR.actif]:null;
const kidsAges=g=>((g&&g.enfants)||[]).map(k=>+k.age).filter(n=>!isNaN(n));
function gDays(){const t=today(),q=GR.quand||{};let a,b;
  if(q.mode==="dates"&&q.du&&q.au&&q.au>=t){a=q.du>t?q.du:t;b=q.au;}
  else if(q.mode==="jour"){a=b=t;}
  else [a,b]=defaultStay();
  return range(a,b).slice(0,21);}
function gWho(g,type){const K=kidsAges(g).sort((a,b)=>a-b),n=g.adultes,A=`${n} adulte${n>1?"s":""}`;
  if(!K.length)return type==="amis"?`${A}, entre amis`:type==="couple"?"En couple":type==="solo"?"Seul·e":A;
  return `${A}, ${K.length>1?`enfants de ${listAnd(K.map(String))} ans`:`un enfant de ${K[0]} an${K[0]>1?"s":""}`}`;}
function gWhen(){const q=GR.quand||{},d=gDays();
  const sm=(a,b)=>a.slice(0,7)===b.slice(0,7)?`${+a.slice(8)} au ${+b.slice(8)} ${F(noon(b),{month:"short"}).replace(".","")}`:`${dshort(a)} au ${dshort(b)}`;
  const w=q.mode==="dates"&&q.au>=today()?`Séjour du ${sm(q.du,q.au)}`:q.mode==="jour"?"Aujourd'hui":`Week-end du ${sm(d[0],d[d.length-1])}`;
  return w;}
/* adéquation d'âge : "all" | "some" | "none" | "neutral" */
function evRange(e){if(e.ageMin!=null||e.ageMax!=null)return[e.ageMin??0,e.ageMax??99];return e.kids?[0,99]:null;}
function fitAges(rg,g){const K=kidsAges(g);
  if(!K.length)return rg&&rg[1]<=12?"none":"all";
  if(!rg)return"neutral";
  const n=K.filter(a=>a>=rg[0]&&a<=rg[1]).length;return n===K.length?"all":n?"some":"none";}
function fitText(fit,rg,K){const pre=rg&&!(rg[0]===0&&rg[1]>=99)?(rg[1]>=99?`Dès ${rg[0]} ans`:`${rg[0]}–${rg[1]} ans`)+" : ":"";
  if(fit==="all"){const w=K.length>1?(K.length===2?"les deux enfants":"tous les enfants"):"adapté à votre enfant";return[pre?pre+w:cap(K.length>1?"pour "+w:w),"ok"];}
  const ok=K.filter(a=>rg&&a>=rg[0]&&a<=rg[1]).sort((a,b)=>a-b),mx=Math.max(...K),mn=Math.min(...K);
  const w=ok.length===1?(ok[0]===mx&&K.length>1?"pour l'aîné seulement":ok[0]===mn&&K.length>1?"pour le plus jeune seulement":`pour l'enfant de ${ok[0]} ans`):`pour les ${listAnd(ok.map(String))} ans`;
  return[pre?pre+w:cap(w),"warn"];}

