const WHO2=()=>[["tous","Tout public"],...(gActive()?[["groupe","Mon groupe"]]:[]),["petits","Tout-petits (0–5)"],["enfants","Enfants (6–11)"],["ados","Ados"],["adultes","Adultes"]];
function evOK(e){if(S.who==="groupe"){const g=gActive();return !g||fitAges(evRange(e),g)!=="none";}return evFits(e,S.who==="groupe"?"tous":S.who);}
function actOK(a){if(S.who==="groupe"){const g=gActive();return !g||fitAges(a.ages||[0,99],g)!=="none";}return fitsWho(a,S.who);}
function defaultStay(){const t=today();let d=t;if(dow(t)===6||dow(t)===0)return[t,dow(t)===6?addDays(t,1):t];while(dow(d)!==5)d=addDays(d,1);return[d,addDays(d,2)];}

/* ---------- partage et copie ---------- */
document.addEventListener("click",e=>{const b=e.target.closest("[data-share]");if(!b)return;e.preventDefault();
  /* le lien n'apparaît qu'une fois : celui de la chose partagée, sinon celui du site */
  const url=b.dataset.url||SITE,site=/^https:\/\/lepetitpref\.fr\/?(#.*)?$/.test(url);
  const text=b.dataset.share+(site?"":"\n\nTrouvé sur Le Petit Préf");
  if(navigator.share){navigator.share({text,url}).catch(()=>{});return;}
  try{navigator.clipboard.writeText(text+"\n"+url).then(()=>toast("Copié : collez-le dans votre groupe"),()=>{fallbackCopy(text+"\n"+url);toast("Copié");});}catch(_){fallbackCopy(text+"\n"+url);toast("Copié");}});

/* ---------- composants ---------- */
function row({lead="",leadCls="",th="",title,metaH="",lines=[],more="",href="",ext=false,tag="li",act=""}){
  const main=`<span class="row-main"><span class="row-title">${title}</span>${metaH?`<span class="row-meta">${metaH}</span>`:""}${lines.filter(l=>l&&l[0]).map(([t,c])=>`<span class="row-meta ${c||""}">${t}</span>`).join("")}</span>`;
  const L=lead!==""?`<span class="row-lead ${leadCls}">${lead}</span>`:"";
  const end=(more||href)?`<span class="row-end">${ic("chev")}</span>`:"";
  let h;
  if(more)h=`<details class="row-d"><summary class="row">${L}${th}${main}${end}</summary><div class="row-more ${th?"th":L?"":"flush"}">${more}</div></details>`;
  else if(href)h=`<a class="row" href="${esc(href)}"${ext?' target="_blank" rel="noopener"':""}${act}>${L}${th}${main}${end}</a>`;
  else return tag==="li"?`<li class="row">${L}${th}${main}</li>`:`<div class="row">${L}${th}${main}</div>`;
  return tag==="li"?`<li>${h}</li>`:h;}
const TH={mer:["t-sea","wave"],nature:["t-nat","leaf"],sortie:["t-act","spark"],sensations:["t-act","spark"],enfants:["t-act","spark"],culture:["t-sea","sail"],sport:["t-nat","bike"],bienetre:["t-sea","drop"],saveurs:["t-food","fork"],marche:["t-food","basket"]};
function thumbOf(a){let[c,n]=TH[a.cat]||["t-act","spark"];
  if(a.kind==="huitres"||a.kind==="poisson")n="shell";else if(a.cat==="saveurs"&&a.kind!=="restaurant"&&a.kind!=="creperie")n="basket";
  if(/vélo|Ride/i.test(a.n))n="bike";if(/Pêche à pied/.test(a.n))n="tide";if(/^Cin[ée]/.test(a.n))n="film";if(/voile/i.test(a.n))n="sail";if(/Thalasso|Aqua/i.test(a.n))n="drop";
  return `<span class="thumb ${c}">${ic(n)}</span>`;}
function statusOf(a,d){const o=openOn(a,d);
  if(/Pêche à pied/.test(a.n)){const l=dayLows(d);return[`Accès libre${l.length?" · basse mer "+hm(new Date(l[0].ms)):""}`,"ok"];}
  if(o)return[`Ouvert${/^(ouvert|week-end)$/.test(o)?"":" · "+esc(o)}`,"ok"];
  if(o===false){const md=d.slice(5),inSeason=a.open.some(r=>r.from<=r.to?(md>=r.from&&md<=r.to):(md>=r.from||md<=r.to));
    return[inSeason?`Fermé le ${F(noon(d),{weekday:"long"})}`:`Fermé en cette saison${a.season?" · "+esc(a.season):""}`,""];}
  if(/Gratuit/.test(a.price||"")&&/^(nature|mer|culture)$/.test(a.cat))return["Accès libre","ok"];
  return["Horaires à vérifier","dim"];}
function placeMore(a){const sh=`${a.n} (${a.town})${a.tel?" · "+a.tel:""}`;
  return `${a.d?`<p>${esc(a.d)}</p>`:""}${a.price||a.season?`<span class="row-meta">${esc([a.price,a.season].filter(Boolean).join(" · "))}</span>`:""}
   <span class="row-links">${telLinks(a.tel)}${a.url?`<a href="${esc(a.url)}" target="_blank" rel="noopener">Site ↗</a>`:""}<a href="${esc(mapsUrl(a))}" target="_blank" rel="noopener">Itinéraire ↗</a><button type="button" data-share="${esc(sh)}" data-url="${esc(a.url||mapsUrl(a))}">Partager</button></span>`;}
const MOIS=["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];
function schedTxt(a){if(!a.open||!a.open.length)return "";const per=r=>r.from==="01-01"&&r.to==="12-31"?"":(()=>{const[m1,d1]=r.from.split("-").map(Number),[m2,d2]=r.to.split("-").map(Number);const md=(m,d,end)=>d===1&&!end?MOIS[m-1]:(end&&d>=28?MOIS[m-1]:d+" "+MOIS[m-1]);return m1===m2?md(m1,d1)+(d1===1&&d2>=28?"":"–"+d2):md(m1,d1)+" à "+md(m2,d2,true);})();
  const JN=["dimanche","lundi","mardi","mercredi","jeudi","vendredi","samedi"],jours=r=>{const o=[..."1234560"].filter(x=>(r.days||"0123456").includes(x));return o.length===7?"tous les jours":listAnd(o.map(x=>JN[+x]));};
  return a.open.map(r=>cap(jours(r))+(r.hours?", "+r.hours:"")+(per(r)?" ("+per(r)+")":"")).join(" ; ");}
function placeRow(a,d,o={}){
  const m=o.metaH??(a.cat==="saveurs"?meta(KIND1[a.kind]||"",esc(townShort(a.town))+(isHere(a.dist,a.town)?"":", "+kmTxt(a.dist,a.town)),isHere(a.dist,a.town)?"à pied":""):meta(esc(townShort(a.town)),kmTxt(a.dist,a.town),agesTxt(a),/^Gratuit/.test(a.price||"")?'<span class="ok">Gratuit</span>':""));
  const lines=o.lines||(a.cat==="marche"&&a.open?[statusOf(a,d),[esc(schedTxt(a)),"dim"]]:[statusOf(a,d)]);
  return row({th:thumbOf(a),title:esc(a.n),metaH:m,lines,more:placeMore(a),tag:o.tag||"li"});}
function evMore(e){const when=e.end&&e.end!==e.date?`Du ${dshort(e.date)} au ${dshort(e.end)}`:cap(dlong(e.date));
  const sh=`${e.title}\n${when}${e.time?" · "+e.time:""} · ${[e.place,e.town].filter(Boolean).join(", ")}`;
  return `${e.desc?`<p>${esc(e.desc)}</p>`:""}<span class="row-meta">${meta(esc(when),esc(e.time||""),esc(e.place||""))}</span>
   <span class="row-links">${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noopener">Source ↗</a>`:""}<button type="button" data-share="${esc(sh)}" data-url="${esc(e.url||"")}">Partager</button></span>`;}
function evRow(e,o={}){const g=o.g,K=kidsAges(g);
  const place=esc(townShort(e.town)||e.place||""),km=kmTxt(evKm(e),e.town);
  const lead=o.lead==="day"?dateLead(o.day||e.date):o.lead==="none"?"":(tShort(e.time)||(evIsLong(e)?"Expo":"—"));
  const until=evIsLong(e)||(e.end&&e.end!==e.date&&o.lead!=="day")?`jusqu'au ${dshort(e.end)}`:"";
  const m=meta(o.lead==="day"?esc(tShort(e.time).replace(/h00$/,"h")):"",place,km,until,evAges(e),e.free?'<span class="ok">Gratuit</span>':"");
  const lines=[];if(g&&K.length){const f=fitAges(evRange(e),g);if(f==="all"||f==="some")lines.push(fitText(f,evRange(e),K));}
  return row({lead,leadCls:o.lead==="day"?"lead-date":o.lead==="none"||tShort(e.time)?"":"is-muted",title:esc(e.title),metaH:m,lines,more:evMore(e),tag:o.tag||"li"});}
/* compatibilité avec les vues reprises (recherche, venir, à propos) */
const eventCard=e=>evRow(e,{tag:"div",lead:"day"});
const actCard=a=>placeRow(a,today(),{tag:"div"});
function card({c="",ic:icn="",title,meta:m="",desc="",extra="",href="",right=""}){
  const cls=/sea|buoy/.test(c)?"t-sea":/food|market/.test(c)?"t-food":/here|nat/.test(c)?"t-nat":"t-act";
  const th=icn?`<span class="thumb ${cls}">${icn}</span>`:"";
  if(extra)return row({th,title,metaH:m,lines:desc?[[desc,""]]:[],more:extra,tag:"div"});
  if(href){const ext=/^https?:/.test(href);return row({th,title:title+(ext?' <span class="dim">↗</span>':""),metaH:m,lines:desc?[[desc,""]]:[],href,ext,tag:"div"});}
  return row({th,title,metaH:m,lines:desc?[[desc,""]]:[],tag:"div"});}
/* couleur du liseré d'un bloc, d'après son titre */
const secCol=t=>{t=String(t).replace(/<[^>]+>/g,"").toLowerCase();
  return /ciné|film|séance/.test(t)?"--i-cine":/manger|déjeuner|dîner|resto|table|marché|huître|saveur|boulang/.test(t)?"--i-food":/transport|trajet|ligne|car |cars|train/.test(t)?"--seagreen":/urgence|sécurité|numéro|santé|pratique|attention|vigilance/.test(t)?"--warn":/nature|balade|sentier|vélo/.test(t)?"--i-nat":/mer|marée|glisse|spot|surf|pêche|plage|bateau|voile/.test(t)?"--i-sea":"--i-act";};
const sec=(title,link="",body="",note="")=>`<section class="sec blk" style="--c:var(${secCol(title)})"><div class="sec-head"><h2 class="sec-title">${title}</h2>${link}</div>${note?`<p class="sec-note">${note}</p>`:""}${body}</section>`;
