/* ===== Pêche à pied ===== */
/* Tailles minimales et quantités autorisées pour la pêche à pied de loisir.
   À remplir uniquement avec des données vérifiées (réglementation en vigueur pour la Loire-Atlantique).
   Format : especes:[{n:"Nom de l'espèce", taille:"x cm", quantite:"…", note:"…"}], source:"intitulé et lien du texte", maj:"AAAA-MM-JJ".
   Tant que la liste est vide, la page affiche « Tailles réglementaires : en cours de vérification ». */
const PECHE={source:"Réglette « Pêche à pied de loisir » du Syndicat mixte de la Baie de Bourgneuf (valable en Loire-Atlantique et Vendée), juin 2023, et fiche pêche à pied du Département de Loire-Atlantique. Repères indicatifs : seule la réglementation officielle fait foi (mairie, Affaires maritimes de Saint-Nazaire).",maj:"juin 2023",
 url:"https://www.baie-bourgneuf.com/wp-content/uploads/2023/06/Reglette-PAP-taille-recommandee-2023.pdf",
 especes:[
  {n:"Coque",taille:"2,7 cm",quantite:"4 kg (≈ 400)"},
  {n:"Palourde japonaise",taille:"3,5 cm",quantite:"3 kg (≈ 150)"},
  {n:"Huître creuse",taille:"5 cm",quantite:"60 huîtres, 5 kg max."},
  {n:"Huître plate",taille:"6 cm",quantite:"",note:"fiche du Département"},
  {n:"Moule",taille:"4 cm",quantite:"5 kg"},
  {n:"Pignon (telline)",taille:"2,5 cm",quantite:"2 kg (≈ 500)"},
  {n:"Couteau",taille:"10 cm",quantite:"",note:"fiche du Département"},
  {n:"Étrille",taille:"6,5 cm",quantite:"",note:"fiche du Département"},
  {n:"Crevette grise",taille:"3 cm",quantite:"",note:"fiche du Département"},
  {n:"Crevette rose",taille:"5 cm",quantite:"",note:"fiche du Département"}],
 regles:["Pas de pêche à moins de 15 m des parcs à huîtres et des bouchots, ni dans leurs allées.","Outils à main seulement (couteau à palourdes, griffe ou serfouette à 3 dents au plus) ; pas d'arrachage.","Ne grattez pas les herbiers de zostères ; laissez les crabes et crevettes porteurs d'œufs.","Certaines zones peuvent être fermées pour raison sanitaire : renseignez-vous en mairie avant de pêcher.","Amende jusqu'à 22 500 € en cas d'infraction."]};
function goodTides(n){const t=today(),out=[];for(let i=0;i<60&&out.length<n;i++){const d=addDays(t,i),c=maxCoef(d),l=dayLows(d);if(c>=70&&l.length)out.push({d,c,l});}return out;}
function vPeche(){return vMer();}
function pecheBody(){const T=goodTides(12),g=ACTS.find(a=>/Pêche à pied/.test(a.n));
  return `<h2 class="part-h" id="s-peche">Pêche à pied</h2><p class="part-sub">Les bonnes marées des prochaines semaines, calculées pour Préfailles.</p>
  ${sec("Prochaines bonnes marées","",T.length?`<ul class="list">${T.map(({d,c,l})=>row({lead:dateLead(d,d===today()),leadCls:"lead-date",title:`Basse mer ${l.map(x=>hm(new Date(x.ms))).join(" et ")}`,metaH:meta(`coef. ${c}`,c>=90?"grande marée":""),lines:[[`Créneau conseillé ${hm(new Date(l[0].ms-75*6e4))}–${hm(new Date(l[0].ms+75*6e4))}`,"ok"]]})).join("")}</ul>`:`<p class="empty">Pas de bonne marée de jour dans les deux prochains mois.</p>`,"Coefficient 70 et plus, basse mer entre 7 h et 19 h. Le créneau va de 1 h 15 avant à 1 h 15 après la basse mer.")}
  ${g?sec("Où aller","",`<ul class="list">${placeRow(g,today())}</ul>`):""}
  ${sec("Sécurité","",`<ul class="tips">
   <li>Regardez l'heure de la basse mer avant de partir et repartez dès que la mer remonte : par grand coefficient, elle revient vite.</li>
   <li>Repérez votre chemin de retour. Les chenaux et les cuvettes se remplissent en premier et peuvent vous couper du rivage.</li>
   <li>N'y allez pas seul, prévenez quelqu'un, gardez un téléphone chargé dans une poche étanche.</li>
   <li>Chaussures fermées : rochers glissants et coquillages coupants.</li>
   <li>Brouillard, orage ou vent qui forcit : on remonte tout de suite.</li>
   <li>Remettez les rochers retournés à leur place et ne prélevez que ce que vous mangerez.</li>
   <li>Personne en difficulté en mer ou sur l'estran : appelez le <a href="tel:196">196</a> (ou le <a href="tel:112">112</a>).</li></ul>`)}
  ${sec("Tailles et quantités","",PECHE.especes.length?`<table class="tbl"><thead><tr><th>Espèce</th><th>Taille min.</th><th>Quantité</th></tr></thead><tbody>${PECHE.especes.map(x=>`<tr><td>${esc(x.n)}${x.note?`<br><span class="dim">${esc(x.note)}</span>`:""}</td><td>${esc(x.taille||"")}</td><td>${esc(x.quantite||"")}</td></tr>`).join("")}</tbody></table><p class="sec-note" style="margin-top:8px">${esc(PECHE.source)}${PECHE.url?` <a href="${PECHE.url}" target="_blank" rel="noopener">Voir la réglette ↗</a>`:""}</p><h3 class="sec-sub" style="margin:14px 0 4px;font-size:15px">Les règles à connaître</h3>${(PECHE.regles||[]).map(r=>`<p class="sec-note" style="margin:6px 0">• ${esc(r)}</p>`).join("")}`:`<p class="textline" style="border-top:0"><b>Tailles réglementaires :</b> en cours de vérification.</p>`)}
  <p class="foot">Certaines zones peuvent être fermées pour raison sanitaire : en cas de doute, appelez la mairie au <a href="tel:0240216037">02 40 21 60 37</a>.</p>`;}

